#include <stdio.h>

int main(void) {
    long long a, b;
    char op;
    scanf("%lld %c %lld", &a, &op, &b);
    switch (op) {
    case '+':
        printf("%lld\n", a + b);
        break;
    case '-':
        printf("%lld\n", a - b);
        break;
    case '*':
        printf("%lld\n", a * b);
        break;
    case '/':
        if (b == 0) {
            printf("ошибка\n");
        } else {
            printf("%lld\n", a / b);
        }
        break;
    case '%':
        if (b == 0) {
            printf("ошибка\n");
        } else {
            printf("%lld\n", a % b);
        }
        break;
    default:
        printf("неизвестная операция\n");
        break;
    }
    return 0;
}

