#include <stdio.h>

int main(void) {
    long long x, y, steps;
    char cmd;
    scanf("%lld %lld %c %lld", &x, &y, &cmd, &steps);
    switch (cmd) {
    case 'N':
    case 'n':
        y += steps;
        break;
    case 'S':
    case 's':
        y -= steps;
        break;
    case 'E':
    case 'e':
        x += steps;
        break;
    case 'W':
    case 'w':
        x -= steps;
        break;
    default:
        break;
    }
    printf("%lld %lld\n", x, y);
    return 0;
}

